import java.io.*;import java.util.*;public class TestClass {    public static void main(String[] args) throws Exception {        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));        StringTokenizer st = new StringTokenizer(br.readLine());        int n = Integer.parseInt(st.nextToken());        int m = Integer.parseInt(st.nextToken());        int[][] a = new int[n][m];        int[] colMax = new int[m];        for (int i = 0; i < n; i++) {            st = new StringTokenizer(br.readLine());            for (int j = 0; j < m; j++) {                int val = Integer.parseInt(st.nextToken());                a[i][j] = val;                if (val > colMax[j]) {                    colMax[j] = val;                }            }        }        int bestIdx = 1;        int bestCount = -1;        long bestSum = -1;        for (int i = 0; i < n; i++) {            int cnt = 0;            long sum = 0;            for (int j = 0; j < m; j++) {                int val = a[i][j];                sum += val;                if (val == colMax[j]) {                    cnt++;                }            }            if (cnt > bestCount || (cnt == bestCount && sum > bestSum)) {                bestCount = cnt;                bestSum = sum;                bestIdx = i + 1;            }        }        System.out.println(bestIdx);    } }